import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aStr = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aStr[i]);
        }

        List<Integer> half1 = new ArrayList<>();
        List<Integer> half2 = new ArrayList<>();
        int maxModSum = 0;

        int sizeHalf1 = 1 << ((n / 2) + (n % 2));
        for (int i = 0; i < sizeHalf1; i++) {
            int sumPart = 0;
            int bitMask = i;
            for (int j = 0; j < 20; j++) {
                if ((bitMask & 1) == 1) {
                    sumPart += a[j];
                }
                bitMask >>= 1;
            }
            half1.add(sumPart % m);
        }
        Collections.sort(half1);

        int sizeHalf2 = 1 << (n / 2);
        for (int i = 0; i < sizeHalf2; i++) {
            int sumPart = 0;
            int bitMask = i;
            for (int j = 0; j < 20; j++) {
                if ((bitMask & 1) == 1) {
                    sumPart += a[(n / 2) + (n % 2) + j];
                }
                bitMask >>= 1;
            }
            sumPart %= m;

            int target = m - sumPart - 1;
            int idx = Collections.binarySearch(half1, target);
            if (idx < 0) {
                idx = -idx - 1;
            }
            int candidate;
            if (idx < half1.size()) {
                candidate = half1.get(idx);
                if (candidate > target && idx - 1 >= 0) {
                    candidate = half1.get(idx - 1);
                }
            } else {
                candidate = half1.get(half1.size() - 1);
            }
            maxModSum = Math.max(maxModSum, Math.max((sumPart + candidate) % m, (sumPart + half1.get(half1.size() - 1)) % m));
        }
        System.out.println(maxModSum);
    }
}
